        CompoundTag compound = new CompoundTag();

        ListTag list = new ListTag();
        for (Death d : deaths) {
            CompoundTag c = d.toNBT(false);
            list.add(c);
        }

        compound.put("Deaths", list);
        buf.writeNbt(compound);
    }

