                float damage = (modifierValue * (float) broom.getLastPlayerSpeed()) / 50F;
                if (damage > 0) {
                    LivingEntity passenger = broom.getControllingPassenger();
                    if (passenger != null) {
                        entity.hurt(ExtendedDamageSources.broomDamage(passenger), damage);
                    }
