private void initializeLidAngle() {
        if (getState() == State.OPEN) {
            previousLidAngle = lidAngle = START_LID_ANGLE;
        } else if (getState() == State.CLOSED) {
            previousLidAngle = lidAngle = 0f;
        }
    }

