protected boolean removeEnchant(Level world, BlockEntityPurifier tile, ItemStack purifyItem, int tick, Enchantment enchant) {
        int enchantmentListID = EnchantmentHelpers.doesEnchantApply(purifyItem, enchant);
        if(enchantmentListID > -1) {
            if(tick >= PURIFY_DURATION) {
                if(!world.isClientSide()) {
                    int level = EnchantmentHelpers.getEnchantmentLevel(purifyItem, enchantmentListID);
                    EnchantmentHelpers.setEnchantmentLevel(purifyItem, enchantmentListID, level - 1);
                }
                tile.setBuckets(tile.getBucketsFloored() - 1, tile.getBucketsRest());
                return true;
            }
            if(world.isClientSide()) {
                tile.showEffect();
            }
        }
        return false;
    }

@Override
    public boolean work(BlockEntityPurifier tile) {
        boolean done = false;

        ItemStack purifyItem = tile.getPurifyItem();
        Level world = tile.getLevel();
        int tick = tile.getTick();

        // Try removing curses
        for (Map.Entry<Enchantment, Integer> entry : EnchantmentHelper.getEnchantments(tile.getPurifyItem()).entrySet()) {
            if (!done && entry.getKey().isCurse()) {
                done = removeEnchant(world, tile, purifyItem, tick, entry.getKey());
            }
        }

        // Try removing bad enchants.
        for(Enchantment enchant : DamageableItemRepairAction.BAD_ENCHANTS) {
            if(!done) {
                if (!(tile.getPurifyItem().getItem() instanceof ItemVengeancePickaxe)
                        || (enchant instanceof EnchantmentVengeance)) {
                    done = removeEnchant(world, tile, purifyItem, tick, enchant);
                }
            }
        }

        return done;
    }

@Override
    public boolean canTick(BlockEntitySanguinaryEnvironmentalAccumulator tile, ItemStack itemStack, int slot, int tick) {
        // Only allow ticking if production slot is empty or if the producing item is the same and
        // there is at least one spot left in the stack.
        if (!tile.getInventory().getItem(BlockEntitySanguinaryEnvironmentalAccumulator.SLOT_ACCUMULATE).isEmpty()
                && tile.getTileWorkingMetadata().canConsume(tile.getInventory()
                .getItem(BlockEntitySanguinaryEnvironmentalAccumulator.SLOT_ACCUMULATE), tile.getLevel())) {
            ItemStack production = tile.getInventory().getItem(tile.getTileWorkingMetadata().getProduceSlot());
            return getRecipe(tile)
                    .map(recipe -> {
                        boolean precondition = false;
                        ItemStack willProduce = willProduceItem(tile, recipe);
                        if (production.isEmpty()) {
                            precondition = true;
                        } else if (!willProduce.isEmpty()
                                && production.getItem() == willProduceItem(tile, recipe).getItem()
                                && Objects.equals(production.getTag(), willProduceItem(tile, recipe).getTag())) {
                            if(production.getCount() + willProduce.getCount() <= production.getMaxStackSize())
                                precondition = true;
                        }
                        return precondition && tile.canWork() && tile.getVirtualTank().getFluidAmount() >= getRequiredFluidAmount(tile, recipe);
                    })
                    .orElse(false);
        }
        return false;
    }

