        } else {
            matrixStackIn.translate(1F, 1.2F, 1F);
            matrixStackIn.mulPose(Axis.XP.rotationDegrees(25F));
            matrixStackIn.mulPose(Axis.YP.rotationDegrees(25F));
            matrixStackIn.mulPose(Axis.YP.rotationDegrees(rotation));
        }

