public void push(T element) {
        if(top == maxSize()) top = 0;
        stack.add(top, element);
        top++;
        if(popBalance < size - 1) popBalance++;
    }

public T pop() {
        if(top - 1 < 0) top = size;
        T element = stack.get(--top);
        popBalance--;
        return element;
    }

