        Map<ItemStack, Float> modifiers = Maps.newHashMap();
        for (Map.Entry<ItemStack, Map<BroomModifier, Float>> entry : broomItems.entrySet()) {
            for (Map.Entry<BroomModifier, Float> itModifiers : entry.getValue().entrySet()) {
