                if (level().isClientSide()) {
                    Minecraft.getInstance().levelRenderer.addParticle(
                            DustParticleOptions.REDSTONE, false,
                            blockPos.getX() + 0.5, blockPos.getY() + 0.5, blockPos.getZ() + 0.5, 1, 0, 0);
                }
            }

            this.remove(RemovalReason.DISCARDED);
        }
    }

