private int getListIndex(int slot) {
        int index = 0;
        for (int i = 0; i < items.length; i++) {
            NonNullList<ItemStack> list = items[i];
            if (slot >= index && slot < index + list.size()) {
                return i;
            }
            index += list.size();
        }
        return -1;
    }

private int getLocalIndex(int slot) {
        int index = 0;
        for (int i = 0; i < items.length; i++) {
            NonNullList<ItemStack> list = items[i];
            if (slot >= index && slot < index + list.size()) {
                return slot - index;
            }
            index += list.size();
        }
        return -1;
    }

