public static boolean isInBounds(float number, float bound, float tolerance) {
        if (number > bound - tolerance && number < bound + tolerance) {
            return true;
        }
        return false;
    }

public static float subtractToZero(float num, float sub) {
        float erg;
        if (num < 0F) {
            erg = num + sub;
            if (erg > 0F) {
                erg = 0F;
            }
        } else {
            erg = num - sub;
            if (erg < 0F) {
                erg = 0F;
            }
        }

        return erg;
    }

