public DistinctIterator(Iterator<T> it, boolean identity) {
        this.it = it;
        this.passed = identity ? Sets.newIdentityHashSet() : Sets.newHashSet();
    }

@Override
    public boolean hasNext() {
        if (next != null) {
            return true;
        }

        while (it.hasNext()) {
            next = it.next();
            if (passed.add(next)) {
                return true;
            }
        }

        return false;
    }

@Override
    public T next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }

        T ret = next;
        next = null;
        return ret;
    }

