public EvictingStack(int size) {
        this.size = size;
        this.stack = Lists.newArrayListWithCapacity(size);
        this.top = 0;
    }

public void push(T element) {
        if(top == maxSize()) top = 0;
        stack.add(top, element);
        top++;
        if(popBalance < size - 1) popBalance++;
    }

public T pop() {
        if(top - 1 < 0) top = size;
        T element = stack.get(--top);
        popBalance--;
        return element;
    }

public int maxSize() {
        return size;
    }

public int currentSize() {
        return popBalance;
    }

public MultitransformIterator(Iterator<? extends F> it, Function<F, Iterator<? extends T>> transformer) {
        this.it = it;
        this.transformer = transformer;
    }

@Override
    public boolean hasNext() {
        if (lastIt.hasNext()) {
            return true;
        }

        while (it.hasNext()) {
            lastIt = this.transformer.apply(it.next());
            if (lastIt.hasNext()) {
                return true;
            }
        }

        return false;
    }

@Override
    public T next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }

        removalIt = lastIt;
        return lastIt.next();
    }

@Override
    public void remove() {
        if (removalIt == null) {
            throw new IllegalStateException("Attempted to call #remove before #next");
        }
        removalIt.remove();
    }

public static <T> Iterator<T> flattenIterableIterator(Iterator<? extends Iterable<T>> it) {
        return new MultitransformIterator<>(it, Iterable::iterator);
    }

