        int existingIndex;
        if((existingIndex = doesEnchantApply(itemStack, enchantment)) >= 0) {
            setEnchantmentLevel(itemStack, existingIndex, level);
        } else {
            itemStack.enchant(enchantment, level);
        }
    }

