        if (!isInsert()) {
            return ingredient;
        }
        return getIngredientComponentStorage().insert(slot, ingredient, simulate);
    }

@Override
    public T extract(int slot, long maxQuantity, boolean simulate) {
        if (!isExtract()) {
            return getComponent().getMatcher().getEmptyInstance();
        }
        return getIngredientComponentStorage().extract(slot, maxQuantity, simulate);
    }

public IngredientComponentStorageWrapped(IIngredientComponentStorage<T, M> ingredientComponentStorage,
                                             boolean read, boolean insert, boolean extract) {
        this.ingredientComponentStorage = ingredientComponentStorage;
        this.read = read;
        this.insert = insert;
        this.extract = extract;
    }

