public IndexIterator(Iterator<Int2ObjectMap.Entry<ItemStack>> slotIterator, ItemStack prototype, int matchFlags) {
            this.slotIterator = slotIterator;
            this.prototype = prototype;
            this.matchFlags = matchFlags;
            this.next = findNext();
        }

protected int findNext() {
            while(slotIterator.hasNext()) {
                Int2ObjectMap.Entry<ItemStack> entry = slotIterator.next();
                int slot = entry.getIntKey();
                ItemStack itemStack = entry.getValue();
                if (ItemMatch.areItemStacksEqual(itemStack, prototype, matchFlags)) {
                    return slot;
                }
            }
            return -1;
        }

@Override
        public boolean hasNext() {
            return next > 0;
        }

@Override
        public Integer next() {
            return nextInt();
        }

@Override
        public int nextInt() {
            if (!hasNext()) {
                throw new NoSuchElementException("Slot out of bounds");
            }
            int next = this.next;
            this.next = findNext();
            return next;
        }

@Override
        public int skip(int n) {
            int skipped = 0;
            while (n > 0 && hasNext()) {
                nextInt();
                skipped++;
            }
            return skipped;
        }

public WrappedIntIterator(IntIterator it) {
            this.it = it;
        }

@Override
        public int nextInt() {
            return it.nextInt();
        }

@Override
        public boolean hasNext() {
            return it.hasNext();
        }

@Override
        public Integer next() {
            return it.next();
        }

