protected int getCapabilityId(Capability<?> capability) {
        for (int i = 0; i < capabilityTypes.length; i++) {
            Capability<?> capabilityType = capabilityTypes[i];
            if (capabilityType == capability) {
                return i;
            }
        }
        return -1;
    }

