public NbtParseException(String msg) {
        super(msg);
    }

public static INbtPathExpression parse(String nbtPathExpression) throws NbtParseException {
        List<INbtPathExpression> expressions = Lists.newArrayList();

        int pos = 0;
        while (pos < nbtPathExpression.length()) {
            boolean handled = false;
            for (INbtPathExpressionParseHandler parseHandler : NbtPath.PARSE_HANDLERS) {
                INbtPathExpressionParseHandler.HandleResult handleResult = parseHandler.handlePrefixOf(nbtPathExpression, pos);
                if (handleResult.isValid()) {
                    pos += handleResult.getConsumedExpressionLength();
                    expressions.add(handleResult.getPrefixExpression());
                    handled = true;
                    break;
                }
            }

            if (!handled) {
                throw new NbtParseException(String.format("Failed to parse expression at pos '%s'",
                        pos, nbtPathExpression));
            }
        }

        return new NbtPathExpressionList(expressions.toArray(new INbtPathExpression[0]));
    }

public NbtPathExpressionList(INbtPathExpression... subExpressions) {
        this.subExpressions = subExpressions;
    }

@Override
    public NbtPathExpressionMatches matchContexts(Stream<NbtPathExpressionExecutionContext> executionContexts) {
        NbtPathExpressionMatches matches = new NbtPathExpressionMatches(executionContexts);
        for (INbtPathExpression subExpression : subExpressions) {
            matches = subExpression.matchContexts(matches.getContexts());
        }
        return matches;
    }

public INbtPathExpression[] getSubExpressions() {
        return subExpressions;
    }

@Override
    public INbtPathNavigation asNavigation(@Nullable INbtPathNavigation child) throws NbtParseException {
        INbtPathNavigation current = null;
        for (int i = subExpressions.length - 1; i >= 0; i--) {
            if (current != null) {
                // Inner node
                current = subExpressions[i].asNavigation(current);
            } else {
                // Leaf
                current = subExpressions[i].asNavigation(null);
            }
        }
        return current;
    }

public NbtPathExpressionMatches(Stream<NbtPathExpressionExecutionContext> matches) {
        this.matches = matches;
    }

public Stream<NbtPathExpressionExecutionContext> getContexts() {
