public void init() {
        if(networkChannel == null) {
            networkChannel = NetworkRegistry.newSimpleChannel(
                    new ResourceLocation(mod.getModId(), "channel_main"), () -> "1.0.0",
                    Predicates.alwaysTrue(), Predicates.alwaysTrue());
        }
