public synchronized int getNext(String key) {
        // Get value from counter map
        Integer nextObject = counters.get(key);
        int next = 0;
        if (nextObject != null) {
            next = nextObject;
        }

        // Handle overflows
        int incr = next + 1;
        if (incr < 0) {
            incr = 0;
        }

        // Store value for next call
        counters.put(key, incr);

        return next;
    }

