@Override
    public RecipeCraftingShapedCustomOutput fromNetwork(ResourceLocation recipeId, FriendlyByteBuf buffer) {
        int i = buffer.readVarInt();
        int j = buffer.readVarInt();
        String s = buffer.readUtf(32767);
        CraftingBookCategory craftingbookcategory = buffer.readEnum(CraftingBookCategory.class);
        NonNullList<Ingredient> nonnulllist = NonNullList.withSize(i * j, Ingredient.EMPTY);

        for(int k = 0; k < nonnulllist.size(); ++k) {
            nonnulllist.set(k, Ingredient.fromNetwork(buffer));
        }

        ItemStack itemstack = buffer.readItem();
        return new RecipeCraftingShapedCustomOutput(this, recipeId, s, craftingbookcategory, i, j, nonnulllist, itemstack);
