public static <T extends Iterator<?>> Matcher<T> isIterator(T value) {
        return new IsEqualIterator<T>(value);
    }

public IsEqualIterator(T equalArg) {
        expectedValue = equalArg;
    }

@Override
    public boolean matches(Object item) {
        T actualValue = (T) item;
        while (expectedValue.hasNext()) {
            if (!actualValue.hasNext()) {
                return false;
            }
            if (!Objects.equals(expectedValue.next(), actualValue.next())) {
                return false;
            }
        }
        if (actualValue.hasNext()) {
            return false;
        }
        return true;
    }

@Override
    public void describeTo(Description description) {
        description.appendValue(expectedValue);
    }

