@Override
    public int compare(ComplexStack o1, ComplexStack o2) {
        if (o1 == null) {
            if (o2 == null) {
                return 0;
            } else {
                return -1;
            }
        } else if (o2 == null) {
            return 1;
        } else if (o1.getGroup() == o2.getGroup()) {
            int m1 = o1.getMeta();
            int m2 = o2.getMeta();
            if (m1 == m2) {
                int c1 = o1.getAmount();
                int c2 = o2.getAmount();
                if (c1 == c2) {
                    ComplexStack.Tag t1 = o1.getTag();
                    ComplexStack.Tag t2 = o2.getTag();
                    if (t1 == null) {
                        if (t2 == null) {
                            return 0;
                        } else {
                            return -1;
                        }
                    } else if (t2 == null) {
                        return 1;
                    } else {
                        return t1.ordinal() - t2.ordinal();
                    }
                }
                return c1 - c2;
            }
            return m1 - m2;
        }
        return o1.getGroup().ordinal() - o2.getGroup().ordinal();
    }

